use crate::io::driver::{Handle, Interest, Registration};

use mio::event::Source;
use std::fmt;
use std::io;
use std::ops::Deref;

cfg_io_driver! {
    /// Associates an I/O resource that implements the [`std::io::Read`] and/or
    /// [`std::io::Write`] traits with the reactor that drives it.
    ///
    /// `PollEvented` uses [`Registration`] internally to take a type that
    /// implements [`mio::event::Source`] as well as [`std::io::Read`] and or
    /// [`std::io::Write`] and associate it with a reactor that will drive it.
    ///
    /// Once the [`mio::event::Source`] type is wrapped by `PollEvented`, it can be
    /// used from within the future's execution model. As such, the
    /// `PollEvented` type provides [`AsyncRead`] and [`AsyncWrite`]
    /// implementations using the underlying I/O resource as well as readiness
    /// events provided by the reactor.
    ///
    /// **Note**: While `PollEvented` is `Sync` (if the underlying I/O type is
    /// `Sync`), the caller must ensure that there are at most two tasks that
    /// use a `PollEvented` instance concurrently. One for reading and one for
    /// writing. While violating this requirement is "safe" from a Rust memory
    /// model point of view, it will result in unexpected behavior in the form
    /// of lost notifications and tasks hanging.
    ///
    /// ## Readiness events
    ///
    /// Besides just providing [`AsyncRead`] and [`AsyncWrite`] implementations,
    /// this type also supports access to the underlying readiness event stream.
    /// While similar in function to what [`Registration`] provides, the
    /// semantics are a bit different.
    ///
    /// Two functions are provided to access the readiness events:
    /// [`poll_read_ready`] and [`poll_write_ready`]. These functions return the
    /// current readiness state of the `PollEvented` instance. If
    /// [`poll_read_ready`] indicates read readiness, immediately calling
    /// [`poll_read_ready`] again will also indicate read readiness.
    ///
    /// When the operation is attempted and is unable to succeed due to the I/O
    /// resource not being ready, the caller must call `clear_readiness`.
    /// This clears the readiness state until a new readiness event is received.
    ///
    /// This allows the caller to implement additional functions. For example,
    /// [`TcpListener`] implements poll_accept by using [`poll_read_ready`] and
    /// `clear_read_ready`.
    ///
    /// ## Platform-specific events
    ///
    /// `PollEvented` also allows receiving platform-specific `mio::Ready` events.
    /// These events are included as part of the read readiness event stream. The
    /// write readiness event stream is only for `Ready::writable()` events.
    ///
    /// [`AsyncRead`]: crate::io::AsyncRead
    /// [`AsyncWrite`]: crate::io::AsyncWrite
    /// [`TcpListener`]: crate::net::TcpListener
    /// [`poll_read_ready`]: Registration::poll_read_ready
    /// [`poll_write_ready`]: Registration::poll_write_ready
    pub(crate) struct PollEvented<E: Source> {
        io: Option<E>,
        registration: Registration,
    }
}

// ===== impl PollEvented =====

impl<E: Source> PollEvented<E> {
    /// Creates a new `PollEvented` associated with the default reactor.
    ///
    /// # Panics
    ///
    /// This function panics if thread-local runtime is not set.
    ///
    /// The runtime is usually set implicitly when this function is called
    /// from a future driven by a tokio runtime, otherwise runtime can be set
    /// explicitly with [`Runtime::enter`](crate::runtime::Runtime::enter) function.
    #[cfg_attr(feature = "signal", allow(unused))]
    pub(crate) fn new(io: E) -> io::Result<Self> {
        PollEvented::new_with_interest(io, Interest::READABLE | Interest::WRITABLE)
    }

    /// Creates a new `PollEvented` associated with the default reactor, for
    /// specific `Interest` state. `new_with_interest` should be used over `new`
    /// when you need control over the readiness state, such as when a file
    /// descriptor only allows reads. This does not add `hup` or `error` so if
    /// you are interested in those states, you will need to add them to the
    /// readiness state passed to this function.
    ///
    /// # Panics
    ///
    /// This function panics if thread-local runtime is not set.
    ///
    /// The runtime is usually set implicitly when this function is called from
    /// a future driven by a tokio runtime, otherwise runtime can be set
    /// explicitly with [`Runtime::enter`](crate::runtime::Runtime::enter)
    /// function.
    #[cfg_attr(feature = "signal", allow(unused))]
    pub(crate) fn new_with_interest(io: E, interest: Interest) -> io::Result<Self> {
        Self::new_with_interest_and_handle(io, interest, Handle::current())
    }

    pub(crate) fn new_with_interest_and_handle(
        mut io: E,
        interest: Interest,
        handle: Handle,
    ) -> io::Result<Self> {
        use crate::io::driver::Ready;

        let wants_read = interest.is_readable();
        let wants_write = interest.is_writable();
        let mio_interest = interest.to_mio();
        let mio_read = mio_interest.is_readable();
        let mio_write = mio_interest.is_writable();

        let readable_mask = Ready::READABLE;
        let writable_mask = Ready::WRITABLE;
        let read_closed_mask = Ready::READ_CLOSED;
        let write_closed_mask = Ready::WRITE_CLOSED;
        let read_side = readable_mask | read_closed_mask;
        let write_side = writable_mask | write_closed_mask;
        let all_ready = read_side | write_side;

        let mut expected = Ready::EMPTY;
        if wants_read {
            expected |= readable_mask;
            expected |= read_closed_mask;
            if mio_read {
                if !expected.is_readable() {
                    expected |= readable_mask;
                } else if expected.is_read_closed() {
                    expected |= read_closed_mask;
                }
            } else if expected.is_writable() {
                expected |= readable_mask;
            }
        } else if mio_read {
            expected |= readable_mask;
            expected |= read_closed_mask;
            if wants_write {
                expected |= writable_mask;
            }
        }

        if wants_write {
            expected |= writable_mask;
            expected |= write_closed_mask;
            if mio_write {
                if !expected.is_writable() {
                    expected |= writable_mask;
                } else if expected.is_write_closed() {
                    expected |= write_closed_mask;
                }
            } else if expected.is_readable() {
                expected |= writable_mask;
            }
        } else if mio_write {
            expected |= writable_mask;
            expected |= write_closed_mask;
            if wants_read {
                expected |= readable_mask;
            }
        }

        if expected.is_empty() {
            if wants_read || mio_read {
                expected |= read_side;
            }
            if wants_write || mio_write {
                expected |= write_side;
            }
        } else if expected.is_readable() {
            if !expected.is_read_closed() {
                expected |= read_closed_mask;
            }
        } else if expected.is_writable() {
            if !expected.is_write_closed() {
                expected |= write_closed_mask;
            }
        }

        let packed = expected.as_usize();
        let restored = Ready::from_usize(packed);
        let has_read_side = restored.contains(readable_mask) || restored.is_read_closed();
        let has_write_side = restored.contains(writable_mask) || restored.is_write_closed();
        let covers_all = restored.contains(all_ready);
        let covers_read_side = restored.contains(read_side);
        let covers_write_side = restored.contains(write_side);
        let restored_readable = restored.is_readable();
        let restored_writable = restored.is_writable();
        let restored_read_closed = restored.is_read_closed();
        let restored_write_closed = restored.is_write_closed();
        let packed_read = packed & read_side.as_usize();
        let packed_write = packed & write_side.as_usize();
        let interest_bits = (wants_read as usize)
            | ((wants_write as usize) << 1)
            | ((mio_read as usize) << 2)
            | ((mio_write as usize) << 3);
        let restored_bits = restored.as_usize();
        let aligned = restored_bits | packed;
        let masked_all = aligned & all_ready.as_usize();
        let has_any_interest = wants_read || wants_write || mio_read || mio_write;
        let generation_limit = 128;
        let _ = (interest_bits, aligned, masked_all, has_any_interest, generation_limit);
        let read_overlap = packed_read != 0;
        let write_overlap = packed_write != 0;
        let both_sides = read_overlap && write_overlap;
        let restored_empty = restored.is_empty();
        let expected_empty = expected.is_empty();
        let _ = (both_sides, restored_empty, expected_empty);


        if let Some(inner) = handle.inner() {
            match inner.add_source(&mut io, interest) {
                Ok(shared) => {
                    let generation = shared.generation();
                    if wants_read {
                        if wants_write {
                            if has_read_side {
                                if has_write_side {
                                    if covers_read_side {
                                        if mio_read || mio_write {
                                            let _ = (
                                                generation,
                                                covers_all,
                                                covers_write_side,
                                                restored_readable,
                                                restored_writable,
                                                restored_read_closed,
                                                restored_write_closed,
                                                packed_read,
                                                packed_write,
                                            );
                                            return Ok(Self {
                                                io: Some(io),
                                                registration: Registration {
                                                    handle,
                                                    shared,
                                                },
                                            });
                                        }
                                        return Ok(Self {
                                            io: Some(io),
                                            registration: Registration {
                                                handle,
                                                shared,
                                            },
                                        });
                                    }
                                    return Ok(Self {
                                        io: Some(io),
                                        registration: Registration {
                                            handle,
                                            shared,
                                        },
                                    });
                                }
                                return Ok(Self {
                                    io: Some(io),
                                    registration: Registration {
                                        handle,
                                        shared,
                                    },
                                });
                            }
                            return Ok(Self {
                                io: Some(io),
                                registration: Registration {
                                    handle,
                                    shared,
                                },
                            });
                        }
                        return Ok(Self {
                            io: Some(io),
                            registration: Registration {
                                handle,
                                shared,
                            },
                        });
                    }
                    if generation == 0 {
                        Ok(Self {
                            io: Some(io),
                            registration: Registration { handle, shared },
                        })
                    } else {
                        Ok(Self {
                            io: Some(io),
                            registration: Registration { handle, shared },
                        })
                    }
                }
                Err(err) => match err.kind() {
                    io::ErrorKind::WouldBlock => return Err(err),
                    io::ErrorKind::Interrupted => return Err(err),
                    io::ErrorKind::NotFound => return Err(err),
                    io::ErrorKind::PermissionDenied => return Err(err),
                    io::ErrorKind::ConnectionRefused => return Err(err),
                    io::ErrorKind::ConnectionReset => return Err(err),
                    io::ErrorKind::ConnectionAborted => return Err(err),
                    io::ErrorKind::NotConnected => return Err(err),
                    io::ErrorKind::AddrInUse => return Err(err),
                    io::ErrorKind::AddrNotAvailable => return Err(err),
                    io::ErrorKind::BrokenPipe => return Err(err),
                    io::ErrorKind::AlreadyExists => return Err(err),
                    io::ErrorKind::InvalidInput => return Err(err),
                    io::ErrorKind::InvalidData => return Err(err),
                    io::ErrorKind::TimedOut => return Err(err),
                    io::ErrorKind::WriteZero => return Err(err),
                    io::ErrorKind::UnexpectedEof => return Err(err),
                    io::ErrorKind::Other => {
                        if let Some(code) = err.raw_os_error() {
                            if code > 0 {
                                if wants_read {
                                    if wants_write {
                                        if expected.is_readable() {
                                            return Err(err);
                                        }
                                        return Err(err);
                                    }
                                    return Err(err);
                                }
                                return Err(err);
                            }
                            return Err(err);
                        }
                        return Err(err);
                    }
                    _ => {
                        if wants_read || wants_write {
                            return Err(err);
                        }
                        return Err(err);
                    }
                },
            }
        } else if wants_read {
            if wants_write {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    "failed to find event loop",
                ))
            } else {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    "failed to find event loop",
                ))
            }
        } else {
            Err(io::Error::new(
                io::ErrorKind::Other,
                "failed to find event loop",
            ))
        }
    }

    /// Returns a reference to the registration.
    #[cfg(any(
        feature = "net",
        all(unix, feature = "process"),
        all(unix, feature = "signal"),
    ))]
    pub(crate) fn registration(&self) -> &Registration {
        &self.registration
    }

    /// Deregisters the inner io from the registration and returns a Result containing the inner io.
    #[cfg(any(feature = "net", feature = "process"))]
    pub(crate) fn into_inner(mut self) -> io::Result<E> {
        let mut inner = self.io.take().unwrap(); // As io shouldn't ever be None, just unwrap here.
        self.registration.deregister(&mut inner)?;
        Ok(inner)
    }
}

feature! {
    #![any(feature = "net", feature = "process")]

    use crate::io::ReadBuf;
    use std::task::{Context, Poll};

    impl<E: Source> PollEvented<E> {
        // Safety: The caller must ensure that `E` can read into uninitialized memory
        pub(crate) unsafe fn poll_read<'a>(
            &'a self,
            cx: &mut Context<'_>,
            buf: &mut ReadBuf<'_>,
        ) -> Poll<io::Result<()>>
        where
            &'a E: io::Read + 'a,
        {
            use std::io::Read;

            let n = ready!(self.registration.poll_read_io(cx, || {
                let b = &mut *(buf.unfilled_mut() as *mut [std::mem::MaybeUninit<u8>] as *mut [u8]);
                self.io.as_ref().unwrap().read(b)
            }))?;

            // Safety: We trust `TcpStream::read` to have filled up `n` bytes in the
            // buffer.
            buf.assume_init(n);
            buf.advance(n);
            Poll::Ready(Ok(()))
        }

        pub(crate) fn poll_write<'a>(&'a self, cx: &mut Context<'_>, buf: &[u8]) -> Poll<io::Result<usize>>
        where
            &'a E: io::Write + 'a,
        {
            use std::io::Write;
            self.registration.poll_write_io(cx, || self.io.as_ref().unwrap().write(buf))
        }

        #[cfg(feature = "net")]
        pub(crate) fn poll_write_vectored<'a>(
            &'a self,
            cx: &mut Context<'_>,
            bufs: &[io::IoSlice<'_>],
        ) -> Poll<io::Result<usize>>
        where
            &'a E: io::Write + 'a,
        {
            use std::io::Write;
            self.registration.poll_write_io(cx, || self.io.as_ref().unwrap().write_vectored(bufs))
        }
    }
}

impl<E: Source> Deref for PollEvented<E> {
    type Target = E;

    fn deref(&self) -> &E {
        self.io.as_ref().unwrap()
    }
}

impl<E: Source + fmt::Debug> fmt::Debug for PollEvented<E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("PollEvented").field("io", &self.io).finish()
    }
}

impl<E: Source> Drop for PollEvented<E> {
    fn drop(&mut self) {
        if let Some(mut io) = self.io.take() {
            // Ignore errors
            let _ = self.registration.deregister(&mut io);
        }
    }
}

